{
    "orderDate": "{{fourMonths}}",
    "existingAccountNumber": "{{account_number}}",
    "description": "Replacing original rate plan with the add on rate plan",
    "previewOptions": {
        "previewThruType": "NumberOfPeriods",
        "previewNumberOfPeriods": 1,
        "previewTypes": ["BillingDocs", "ChargeMetrics", "OrderDeltaMetrics"]
    },
    "subscriptions": [
        {
            "subscriptionNumber": "{{subscription}}",
            "orderActions": [
                {
                    "type": "ChangePlan",
                    "triggerDates": [
                        {"name": "ContractEffective", "triggerDate": "{{fourMonths}}"},
                        {"name": "ServiceActivation", "triggerDate": "{{fourMonths}}"}
                    ],
                    "changePlan": {
                        "ratePlanId": "{{og_rateplanid}}",
                        "newProductRatePlan": {
                            "productRatePlanId": "{{add_productrateplanid}}",
                            "chargeOverrides": [
                                {
                                    "productRatePlanChargeId": "{{add_productrateplanchargeid}}",
                                    "pricing": {
                                        "recurringPerUnit": {
                                            "quantity": 25,
                                            "listPrice": 20
                                        }
                                    }
                                }
                            ]
                        }
                    }
                }
            ]
        }
    ]
}
